{"name": "update_employee_titles_and_phone", "query": "
-- Task 2a: Change Andrew Adams title to CEO
UPDATE "Employee" SET "Title" = 'CEO' WHERE "EmployeeId" = 1;

-- Task 2b: Update Nancy Edwards phone number
UPDATE "Employee" SET "Phone" = '+1 (403) 555-9999' WHERE "EmployeeId" = 2;

-- Task 2c: Change all IT Staff to IT Specialist
UPDATE "Employee" SET "Title" = 'IT Specialist' WHERE "Title" = 'IT Staff';
"}

{"name": "reassign_customers_to_new_employees", "query": "
-- Task 3a: Assign customers 1, 2, 3 to Sarah Johnson (EmployeeId = 9)
UPDATE "Customer" SET "SupportRepId" = 9 WHERE "CustomerId" IN (1, 2, 3);

-- Task 3b: Assign customers 4, 5, 6 to Mike Chen (EmployeeId = 10)
UPDATE "Customer" SET "SupportRepId" = 10 WHERE "CustomerId" IN (4, 5, 6);
"}

{"name": "reorganize_reporting_structure", "query": "
-- Task 4: Change Sarah (9) and Mike (10) to report to Andrew Adams (EmployeeId = 1)
UPDATE "Employee" SET "ReportsTo" = 1 WHERE "EmployeeId" IN (9, 10);
"}

