{"name": "delete_robert_king", "query": "
-- Task 6: Robert King (EmployeeId=7) reports to Michael Mitchell (EmployeeId=6)
-- No employees report to Robert, and no customers are assigned to Robert
-- (confirmed by pre-checks). Safe to delete directly.

-- Reassign any employees reporting to Robert to his manager (EmployeeId=6) - none found but safe to run
UPDATE "Employee" SET "ReportsTo" = 6 WHERE "ReportsTo" = 7;

-- Reassign any customers assigned to Robert to his manager (EmployeeId=6) - none found but safe to run
UPDATE "Customer" SET "SupportRepId" = 6 WHERE "SupportRepId" = 7;

-- Now delete Robert King
DELETE FROM "Employee" WHERE "EmployeeId" = 7;
"}

{"name": "promote_laura_add_salary_column", "query": "
-- Task 7a: Promote Laura Callahan to Senior IT Specialist
UPDATE "Employee" SET "Title" = 'Senior IT Specialist' WHERE "EmployeeId" = 8;

-- Task 7b: Add salary column to Employee table
ALTER TABLE "Employee" ADD COLUMN IF NOT EXISTS "salary" DECIMAL;

-- Task 7c: Set Laura's salary to 75000.00 and all others to 50000.00
UPDATE "Employee" SET "salary" = 50000.00;
UPDATE "Employee" SET "salary" = 75000.00 WHERE "EmployeeId" = 8;
"}

